// 1. Une structure de données SIMPLE pour franchir la frontière (un record, sans logique métier).
record LearnerDto(String id, String nom, String email) {}

// 2. Le use case renvoie le DTO, jamais l'entité du domaine.
class GetLearner {
    private final LearnerRepository repo;
    GetLearner(LearnerRepository repo) { this.repo = repo; }

    LearnerDto handle(UUID id) {
        Learner learner = repo.findById(id);   // l'entité du domaine reste À L'INTÉRIEUR
        return toDto(learner);                 // on mappe AU BORD, juste avant de sortir
    }

    // 3. Le mapping domaine -> DTO se fait à la frontière, pas dans le domaine.
    private LearnerDto toDto(Learner l) {
        return new LearnerDto(l.id().toString(), l.nom(), l.email());
    }
}
// Résultat : seule une structure de données simple (LearnerDto) traverse la frontière.
// Le monde extérieur ne dépend plus de l'entité Learner : le couplage interne/externe est évité.
